const ctx = $('01.2 Build run context').item.json;
const attemptStart = $('01.3 Mark phase1 attempt start').item.json.phase1AttemptStartedAt;
const response = $input.first().json;
const statusCode = response.statusCode;
const body = response.body || {};

if (statusCode !== undefined && statusCode >= 200 && statusCode < 300 && body.phase1ControlReport) {
  return [{
    json: {
      processInstanceId: ctx.processInstanceId,
      correlationId: ctx.correlationId,
      workflowId: $workflow.id,
      receivedAt: ctx.receivedAt,
      outcome: "REPORT",
      report: body.phase1ControlReport,
      httpErrorCode: null,
      n8nErrorCode: null,
      explanation: null,
      phase1AttemptStartedAt: attemptStart,
      gateDecisionAt: null,
      callerOk: true,
      callerStatusCode: statusCode,
      canonicalInvoice: body.canonicalInvoice,
    },
  }];
}

if (statusCode !== undefined) {
  const detail = body.detail && typeof body.detail === "object" ? body.detail : {};
  const httpErrorCode = detail.error_code || "BATCH_ITEM_PROCESSING_FAILED";
  const callerDetail = detail.detail || response.message || "Invoice processing failed.";
  return [{
    json: {
      processInstanceId: ctx.processInstanceId,
      correlationId: ctx.correlationId,
      workflowId: $workflow.id,
      receivedAt: ctx.receivedAt,
      outcome: "HTTP_ERROR",
      report: null,
      httpErrorCode,
      n8nErrorCode: null,
      explanation: callerDetail,
      phase1AttemptStartedAt: attemptStart,
      gateDecisionAt: null,
      callerOk: false,
      callerStatusCode: statusCode,
      callerErrorCode: httpErrorCode,
      callerDetail,
    },
  }];
}

// No statusCode at all: a genuine connection-level failure (03.1's error output).
const errObj = response.error || {};
const errMessage = (errObj.message || errObj || response.message || "").toString();
const errCode = (errObj.code || "").toString();
const isTimeout = /ETIMEDOUT|ECONNABORTED/i.test(errCode) || /timeout/i.test(errMessage);
const outcome = isTimeout ? "TIMEOUT" : "TRANSPORT_FAILURE";
const n8nErrorCode = isTimeout ? "INVOICE_PROCESSING_SERVICE_TIMEOUT" : "INVOICE_PROCESSING_SERVICE_UNAVAILABLE";
const explanation = errMessage || "Invoice processing failed.";

return [{
  json: {
    processInstanceId: ctx.processInstanceId,
    correlationId: ctx.correlationId,
    workflowId: $workflow.id,
    receivedAt: ctx.receivedAt,
    outcome,
    report: null,
    httpErrorCode: null,
    n8nErrorCode,
    explanation,
    phase1AttemptStartedAt: attemptStart,
    gateDecisionAt: null,
    callerOk: false,
    callerStatusCode: 503,
    callerErrorCode: n8nErrorCode,
    callerDetail: explanation,
  },
}];

// No weak fallback: a missing crypto.randomUUID must fail visibly rather
// than mint a low-entropy identity for evidence.
// The n8n JS Task Runner sandbox does not expose a bare `crypto` global
// (confirmed against the real pinned n8nio/n8n:2.33.7 image) -- the built-in
// must be required explicitly, and require() itself is denied unless
// allow-listed (NODE_FUNCTION_ALLOW_BUILTIN=crypto, set on the n8n
// container -- see docker-compose.phase1-upload-demo.yml). No weak
// fallback: an unavailable/disallowed crypto module must fail visibly
// rather than mint a low-entropy identity for evidence.
let randomUUID;
try {
  randomUUID = require("crypto").randomUUID;
} catch (e) {
  randomUUID = undefined;
}
if (typeof randomUUID !== "function") {
  throw new Error(
    "SECURE_UUID_UNAVAILABLE: refusing to mint a weak identifier for correlationId/processInstanceId without crypto.randomUUID() (require(\"crypto\") must be allow-listed via NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance)."
  );
}
const correlationId = randomUUID();
const processInstanceId = randomUUID();

const item = $input.first();
return [{
  json: {
    ...item.json,
    correlationId,
    processInstanceId,
    receivedAt: new Date().toISOString(),
  },
  binary: item.binary,
}];

// Reconciles the shared subworkflow's minimal { activityExecution } return
// with 04.1's own envelope (04.1 is this workflow's sole, unambiguous
// predecessor here -- no branch multiplicity to resolve) to rebuild the
// exact caller-facing batch-item response shape the Batch Demo caller
// already depends on.
const envelope = $('04.1 Build control report').item.json;
const { activityExecution } = $input.first().json;

const responseBody = envelope.outcome === "REPORT"
  ? { ok: true, statusCode: envelope.callerStatusCode, canonicalInvoice: envelope.canonicalInvoice, phase1ControlReport: envelope.report }
  : { ok: false, statusCode: envelope.callerStatusCode, errorCode: envelope.callerErrorCode, detail: envelope.callerDetail };

return [{ json: { ...responseBody, activityExecution } }];

// A6a synthetic TCMS demo: decide whether the DigiTax Risk Review advisory
// call is needed at all, per the accepted A6a-auth-boundary-amendment.md
// boundary ("call DigiTax Risk Review only when the accepted gate requires
// it"). This node never recomputes or re-implements a Phase-1 control -- it
// only reads the already-authoritative phase1ControlReport.status field the
// real API produced, exactly as documented in
// docs/invoice_phase1/control_catalog.md's status aggregation rules
// ("unauffaellig: all applicable automated controls passed").
//
// - no report at all (ok === false, a technical/HTTP failure upstream) ->
//   the advisory branch cannot run either; routingStatus TECHNICAL_FAILURE.
// - report.status === "unauffaellig" -> a clean report; stop the advisory
//   branch with NO_RISK_REVIEW_REQUIRED and create no request at all (per
//   A6a-flow1a-synthetic-demo-request.md point 5), saving the round trip.
// - otherwise -> a finding-bearing report; build the exact RiskReviewRequest
//   v1 body from the report's own non-passed controls.
const merged = $input.first().json;
const ctx = $('01.2 Build run context').item.json;
const organizationId = $('01.1 Receive batch item').item.json.body.organizationId;

const ok = merged.ok === true;
const report = ok ? merged.phase1ControlReport : null;
const activityExecution = merged.activityExecution;

if (!ok || !report) {
  return [{
    json: {
      ...merged,
      needsRiskReview: false,
      routingStatus: "TECHNICAL_FAILURE",
      riskReviewReport: null,
    },
  }];
}

if (report.status === "unauffaellig") {
  return [{
    json: {
      ...merged,
      needsRiskReview: false,
      routingStatus: "NO_RISK_REVIEW_REQUIRED",
      riskReviewReport: null,
    },
  }];
}

// Finding-bearing report: select exactly the controls the accepted
// RiskReviewRequest v1 schema accepts as findings (failed / not_reliable /
// not_run -- never "passed" or "not_applicable"). officialRuleIds is
// populated only from a control's own structured schematronFindings (e.g.
// STR-004); every other control reports an empty array, never invented.
const findings = (report.controls || [])
  .filter((c) => ["failed", "not_reliable", "not_run"].includes(c.outcome))
  .map((c) => ({
    controlId: c.controlId,
    outcome: c.outcome,
    severity: c.severity,
    reasonCodes: c.reasonCodes || [],
    message: c.message ?? null,
    evidenceRefs: c.evidenceRefs || [],
    ruleVersion: c.ruleVersion,
    officialRuleIds:
      c.details && Array.isArray(c.details.schematronFindings)
        ? c.details.schematronFindings.map((f) => f.ruleId)
        : [],
  }));

// A6a correction round 1 (section 2): SHA-256 over the accepted
// canonical-json-v1 serialization (object keys sorted recursively at
// every nesting level) of the exact, already-assembled evidence objects --
// computed here, once; never recomputed by DigiTax Risk Review itself, and
// never mutated afterward. Deterministic regardless of source key-insertion
// order, so this hash equals the hash the accepted A5b TCMS evidence
// service independently recomputes after a JSONB round trip (PostgreSQL
// jsonb does not preserve object key order). The functions below are
// embedded verbatim from examples/n8n/vendor/canonicalJson.js -- a
// byte-for-byte port of A5b's server/utils/canonicalJson.ts -- never
// hand-edited between the markers; never read from disk at n8n runtime.
// GENERATED-CANONICAL-JSON-BEGIN: regenerate via node examples/n8n/scripts/sync-embedded-literals.mjs
const CANONICAL_JSON_VERSION = "canonical-json-v1";

function canonicalJsonStringifyValue(value) {
  if (value === undefined || value === null) {
    return "null";
  }
  if (typeof value === "boolean" || typeof value === "string") {
    return JSON.stringify(value);
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw new TypeError("canonicalJsonStringify: cannot serialize a non-finite number");
    }
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map((item) => canonicalJsonStringifyValue(item)).join(",")}]`;
  }
  if (typeof value === "object") {
    const record = value;
    const keys = Object.keys(record)
      .filter((key) => record[key] !== undefined)
      .sort();
    return `{${keys
      .map((key) => `${JSON.stringify(key)}:${canonicalJsonStringifyValue(record[key])}`)
      .join(",")}}`;
  }
  throw new TypeError(`canonicalJsonStringify: unsupported value type ${typeof value}`);
}

function canonicalJsonStringify(value) {
  return canonicalJsonStringifyValue(value);
}

function canonicalPayloadSha256(payload) {
  const nodeCrypto = require("crypto");
  return nodeCrypto
    .createHash("sha256")
    .update(canonicalJsonStringify(payload), "utf8")
    .digest("hex");
}
// GENERATED-CANONICAL-JSON-END
const activityExecutionSha256 = canonicalPayloadSha256(activityExecution);
const controlReportSha256 = canonicalPayloadSha256(report);

const riskReviewRequest = {
  schemaVersion: "1.1.0",
  // requestId/correlationId are never freshly minted here -- they reuse the
  // two secure identifiers 01.2 already generated once for this run
  // (processInstanceId is otherwise evidence-only and never sent to any
  // API; correlationId already went to the Phase-1 API as
  // X-Correlation-ID). Reusing processInstanceId as requestId is what makes
  // a direct replay of this exact request body against DigiTax Risk Review
  // provably idempotent -- see the A6a evidence folder's retry case.
  requestId: ctx.processInstanceId,
  correlationId: ctx.correlationId,
  organizationId,
  processId: activityExecution.definitionRef.processId,
  processVersion: activityExecution.definitionRef.processVersion,
  activityId: activityExecution.definitionRef.activityId,
  activityVersion: activityExecution.definitionRef.activityVersion,
  processInstanceId: ctx.processInstanceId,
  sourceExecutionId: activityExecution.executionId,
  activityExecutionRef: `evidence://activity-execution/${activityExecution.executionId}`,
  activityExecutionSha256,
  controlReportRef: `evidence://phase1-control-report/${report.reportId}`,
  controlReportSha256,
  findings,
  riskCatalogVersion: "flow1a-risk-catalog-2026-08-14",
  triggerPolicyVersion: "flow1a-trigger-policy-1.0.0",
};

return [{
  json: {
    ...merged,
    needsRiskReview: true,
    riskReviewRequest,
  },
}];

// Never re-derives or rewrites the deterministic finding: on a real 2xx the
// exact schema-valid RiskReviewReport is attached verbatim, and its own
// `disposition` field (already one of NO_RISK_REVIEW_REQUIRED /
// RISK_REVIEW_PROPOSED / EVIDENCE_INSUFFICIENT / TECHNICAL_FAILURE -- the
// same enum this bundle's routingStatus uses) becomes routingStatus
// unchanged. Any non-2xx or connection-level failure from the DigiTax Risk
// Review call itself is a TECHNICAL_FAILURE of the *advisory* branch only --
// it never discards or overwrites the already-produced, already-assembled
// phase1ControlReport/activityExecution evidence, which the prior node
// (04.3) still carries through unchanged.
const prior = $('04.3 Evaluate risk review gate').item.json;
const response = $input.first().json;
const statusCode = response.statusCode;
const body = response.body || {};

if (statusCode !== undefined && statusCode >= 200 && statusCode < 300 && body.disposition) {
  return [{
    json: {
      ...prior,
      riskReviewReport: body,
      routingStatus: body.disposition,
    },
  }];
}

return [{
  json: {
    ...prior,
    riskReviewReport: null,
    routingStatus: "TECHNICAL_FAILURE",
  },
}];

// Final convergence point for both the "no risk review needed/possible"
// gate branch (04.3, needsRiskReview === false) and the real call branch
// (04.6). Builds the bounded result bundle required by
// A6a-auth-boundary-amendment.md -- phase1ControlReport, activityExecution,
// optional riskReviewReport, and routingStatus -- additively alongside the
// pre-existing {ok, statusCode, canonicalInvoice} / {ok:false, errorCode,
// detail} shape the Flow 1a Batch Demo browser dashboard already depends on
// (examples/n8n/README.md's "Batch and profile-comparison demo" section),
// so this extension never breaks that existing caller.
const e = $input.first().json;

const bundle = e.ok
  ? {
      ok: true,
      statusCode: e.statusCode,
      canonicalInvoice: e.canonicalInvoice,
      phase1ControlReport: e.phase1ControlReport,
      activityExecution: e.activityExecution,
      riskReviewReport: e.riskReviewReport,
      routingStatus: e.routingStatus,
    }
  : {
      ok: false,
      statusCode: e.statusCode,
      errorCode: e.errorCode,
      detail: e.detail,
      phase1ControlReport: null,
      activityExecution: e.activityExecution,
      riskReviewReport: null,
      routingStatus: e.routingStatus,
    };

return [{ json: bundle }];
